<style>
.product-picker{position:fixed;z-index:1000;display:flex;flex-direction:column;background:#fff;border:1px solid #d1dbe8;border-radius:12px;box-shadow:0 14px 45px #18315330;padding:12px;color:#20334f;font-family:Arial,sans-serif;overflow:hidden}.product-picker[hidden]{display:none}.picker-head{display:flex;align-items:center;justify-content:space-between;margin-bottom:8px;font-size:14px}.picker-head button{border:0;padding:2px 8px;font-size:22px;background:transparent}.picker-category{display:flex;align-items:center;gap:12px;font-size:12px;margin-bottom:8px}.picker-category select{flex:1;min-width:0;border:1px solid #d3dbe6;border-radius:6px;padding:8px;background:#f5f7fa;color:#20334f}.product-picker>input{flex-shrink:0;width:100%;border:1px solid #d3dbe6;border-radius:6px;padding:10px;margin-bottom:8px;font:inherit;font-size:13px}.picker-results{overflow:auto;min-height:0;flex:1;overscroll-behavior:contain}.picker-option{display:flex;gap:12px;align-items:center;width:100%;padding:9px;text-align:left;border:0;border-bottom:1px solid #edf0f5;border-radius:5px;box-shadow:none}.picker-option:hover,.picker-option.is-active{background:#edf3fb}.picker-thumbnail{display:grid;place-items:center;flex-shrink:0;width:58px;height:66px;background:#f4f6f9;border:1px solid #e4e9f0;border-radius:5px;font-size:10px;color:#8792a2;text-align:center}.picker-thumbnail img{width:100%;height:100%;object-fit:contain;border-radius:4px}.picker-description{display:flex;flex-direction:column;gap:4px;min-width:0}.picker-description strong{color:#203b60;font-size:14px}.picker-description>span{font-size:12px;overflow-wrap:anywhere}.picker-description small{font-size:10px;color:#8792a2}.picker-count{font-size:11px;color:#8792a2;margin:8px 0 0}.picker-empty{padding:16px 8px;font-size:13px;color:#738094;line-height:1.5}

